import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

// Single fused elementwise Tanh kernel (fast-math optimized).
// tanh(x) = sign(x) * (1 - e) / (1 + e), e = __expf(-2*|x|) in (0, 1]:
// numerically stable, branch-free, low instruction count. float4
// vectorized loads/stores with evict-first streaming hints (__ldcs/
// __stcs) keep L2 clean for this purely streaming, zero-reuse kernel.
// Optimization (new): minimize register pressure to close the
// occupancy gap. Profiler shows achieved occupancy (81.2%) matching
// the register-allocation ceiling: at 39 regs/thread with 128-thread
// blocks, only 13 blocks (1664 of 2048 threads) fit per 64K-register
// SM, throttling latency hiding for this DRAM-bound (93%) kernel.
// Reworking the loop to carry one float4 payload instead of two and
// capping the kernel at 32 registers via __launch_bounds__(128, 16)
// lets a full 16 blocks (2048 threads, 100% occupancy) reside per
// SM, putting more independent loads in flight to saturate the DRAM
// pipeline. The last (up to 3) tail elements are handled by the
// first threads, so exactly one kernel launch is needed.
__device__ __forceinline__ float fast_tanhf(float x) {
    const float e = __expf(-2.0f * fabsf(x));  // in (0, 1], never overflows
    const float t = __fdividef(1.0f - e, 1.0f + e);
    return copysignf(t, x);
}
__global__ void __launch_bounds__(256, 8) tanh_kernel(
                            const float* __restrict__ in,
                            float* __restrict__ out,
                            const long n) {
    const long n4 = n >> 2;  // number of full float4 groups
    const long tid = (long)blockIdx.x * blockDim.x + threadIdx.x;
    const long stride = (long)gridDim.x * blockDim.x;
    const float4* in4  = reinterpret_cast<const float4*>(in);
    float4*       out4 = reinterpret_cast<float4*>(out);
    // Single float4 payload per grid-stride iteration: only 4 data
    // registers stay live, and the loop still issues back-to-back
    // independent streaming loads across iterations, so memory-level
    // parallelism comes from more resident warps, not fatter threads.
    for (long idx = tid; idx < n4; idx += stride) {
        float4 a = __ldcs(&in4[idx]);
        a.x = fast_tanhf(a.x);
        a.y = fast_tanhf(a.y);
        a.z = fast_tanhf(a.z);
        a.w = fast_tanhf(a.w);
        __stcs(&out4[idx], a);
    }
    const long tail_start = n4 << 2;
    if (tid < n - tail_start) {
        const long i = tail_start + tid;
        __stcs(&out[i], fast_tanhf(__ldcs(&in[i])));
    }
}

torch::Tensor tanh_forward(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "Input must be float32");
    TORCH_CHECK(x.is_contiguous(), "Input must be contiguous");

    auto out = torch::empty_like(x);
    const long n = x.numel();
    if (n == 0) return out;

    // Launch config (occupancy opt): use 256-thread blocks paired with
    // __launch_bounds__(256, 8) so exactly 8 blocks = 2048 threads are
    // resident per SM. This keeps the same 100% theoretical occupancy
    // target while halving the number of CTAs the scheduler must turn
    // over, reducing CTA tail/scheduling overhead for this DRAM-bound
    // streaming kernel and targeting the measured theoretical-vs-achieved
    // occupancy gap. Grid-stride semantics and memory access pattern are
    // unchanged.
    const int threads = 256;
    const long n4 = (n + 3) >> 2;
    long blocks = (n4 + threads - 1) / threads;
    // Cap the grid; grid-stride loop covers the rest.
    const long max_blocks = 65535L * 8L;
    if (blocks > max_blocks) blocks = max_blocks;

    tanh_kernel<<<(int)blocks, threads>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        n);

    return out;
}
"""

cpp_src = "torch::Tensor tanh_forward(torch::Tensor x);"

_tanh_mod = load_inline(
    name="tanh_cuda_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["tanh_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a Tanh activation using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _tanh_mod.tanh_forward(x)

